rawText:
{
  "rows": [
    {
      "segment_index": 1,
      "he": "פרק 7: בעיות בתחום אנרגיה וקפיצים",
      "he_niqqud": "פֶּרֶק 7: בְּעָיוֹת בִּתְחוּם אֶנֶרְגְּיָה וּקְפִיצִים",
      "translit": "Perek 7: be'ayot bitkhum energiah u-kfitsim",
      "ru": "Глава 7: Задачи в области энергии и пружин"
    },
    {
      "segment_index": 2,
      "he": "שאלה 7.1:",
      "he_niqqud": "שְׁאֵלָה 7.1:",
      "translit": "She'elah 7.1:",
      "ru": "Вопрос 7.1:"
    },
    {
      "segment_index": 3,
      "he": "בתרשים מתואר קו ייצור של מוצר M.",
      "he_niqqud": "בַּתַּרְשִׁים מְתֹאָר קַו יִצּוּר שֶׁל מוּצָר M.",
      "translit": "Ba-tarsim meto'ar kav yitsur shel mutsar M.",
      "ru": "На схеме показана производственная линия изделия M."
    },
    {
      "segment_index": 4,
      "he": "כאשר המחסנית נפתחת, נופל מוצר אחד על השולחן האופקי.",
      "he_niqqud": "כַּאֲשֶׁר הַמַּחְסָנִית נִפְתַּחַת, נוֹפֵל מוּצָר אֶחָד עַל הַשֻּׁלְחָן הָאֹפְקִי.",
      "translit": "Ka'asher ha-makhsanit niftakhat, nofel mutsar ekhad al ha-shulkhan ha-ofki.",
      "ru": "Когда кассета открывается, одно изделие падает на горизонтальный стол."
    },
    {
      "segment_index": 5,
      "he": "ברגע זה משתחרר קפיץ דרוך K המעניק למוצר דחיפה, והוא מתקדם לאורך הקטע AB שעל השולחן האופקי (ראה תרשים).",
      "he_niqqud": "בְּרֶגַע זֶה מִשְׁתַּחְרֵר קְפִיץ דָּרוּךְ K הַמַּעֲנִיק לַמּוּצָר דְּחִיפָה, וְהוּא מִתְקַדֵּם לְאֹרֶךְ הַקֶּטַע AB שֶׁעַל הַשֻּׁלְחָן הָאֹפְקִי (רְאֵה תַּרְשִׁים).",
      "translit": "B'rega ze mishtakhrer kfits darukh K ha-ma'anik la-mutsar dkhifa, ve-hu mitkadem le-orekh ha-keta AB she-al ha-shulkhan ha-ofki (re'e tarsim).",
      "ru": "В этот момент освобождается взведённая пружина K, которая толкает изделие, и оно продвигается вдоль отрезка AB на горизонтальном столе (см. схему)."
    },
    {
      "segment_index": 6,
      "he": "ידועים:\nמשקל המוצר: G = 5N\nמקדם החיכוך בין המוצר לבין השולחן האופקי: μ = 0.1\nקבוע הקפיץ: c = 2_{N/cm}\nאורך הקפיץ במצב חופשי: L_1 = 180_{mm}\nאורך הקפיץ במצב דרוך: L_2 = 130_{mm}\nתאוצת הכובד: g = 9.81_{m/sec^2}",
      "he_niqqud": "יְדוּעִים:\nמִשְׁקַל הַמּוּצָר: G = 5N\nמְקַדֵּם הַחִכּוּךְ בֵּין הַמּוּצָר לְבֵין הַשֻּׁלְחָן הָאֹפְקִי: μ = 0.1\nקְבוּעַ הַקְּפִיץ: c = 2_{N/cm}\nאֹרֶךְ הַקְּפִיץ בְּמַצָּב חָפְשִׁי: L_1 = 180_{mm}\nאֹרֶךְ הַקְּפִיץ בְּמַצָּב דָּרוּךְ: L_2 = 130_{mm}\nתְּאוּצַת הַכֹּבֶד: g = 9.81_{m/sec^2}",
      "translit": "Yedu'im:\nMishkal ha-mutsar: G = 5N\nMekadem ha-khibukh bein ha-mutsar le-vein ha-shulkhan ha-ofki: μ = 0.1\nKeva ha-kfits: c = 2_{N/cm}\nOrekh ha-kfits be-matsav khofshi: L_1 = 180_{mm}\nOrekh ha-kfits be-matsav darukh: L_2 = 130_{mm}\nTe'utsat ha-koved: g = 9.81_{m/sec^2}",
      "ru": "Известно:\nВес изделия: G = 5N\nКоэффициент трения между изделием и горизонтальным столом: μ = 0.1\nЖесткость пружины: c = 2_{N/cm}\nДлина пружины в свободном состоянии: L_1 = 180_{mm}\nДлина пружины во взведённом состоянии: L_2 = 130_{mm}\nУскорение свободного падения: g = 9.81_{m/sec^2}"
    },
    {
      "segment_index": 7,
      "he": "חשב את מהירות המוצר בנקודה B (V_B). המידות בתרשים נתונות במ\"מ. (בחישוב המהירות אין להתייחס לנפילת המוצר מהמחסנית, אלא אך ורק לתנועתו על גבי השולחן).",
      "he_niqqud": "חַשֵּׁב אֶת מְהִירוּת הַמּוּצָר בִּנְקֻדָּה B (V_B). הַמִּדּוֹת בַּתַּרְשִׁים נְתוּנוֹת בְּמ\"מ. (בְּחִשּׁוּב הַמְּהִירוּת אֵין לְהִתְיַחֵס לִנְפִילַת הַמּוּצָר מֵהַמַּחְסָנִית, אֶלָּא אַךְ וְרַק לִתְנוּעָתוֹ עַל גַּבֵּי הַשֻּׁלְחָן).",
      "translit": "Khashev et mehirut ha-mutsar bi-nekudah B (V_B). Ha-midot ba-tarsim netunot be-m\"m. (Be-khishuv ha-mehirut ein le-hityakhes li-nefilat ha-mutsar me-ha-makhsanit, ela akh ve-rak li-tnu'ato al gabei ha-shulkhan).",
      "ru": "Рассчитайте скорость изделия в точке B (V_B). Размеры на схеме даны в мм. (При расчете скорости не следует учитывать падение изделия из кассеты, а только его движение по столу)."
    },
    {
      "segment_index": 8,
      "he": "הערה: האנרגיה הפוטנציאלית E האצורה בקפיץ במצב A שווה: E = \\frac{c \\cdot \\Delta L^2}{2}\nכאן: \\Delta L = L_1 - L_2",
      "he_niqqud": "הֶעָרָה: הָאֶנֶרְגְּיָה הַפּוֹטֶנְצִיָאלִית E הָאֲצוּרָה בַּקְּפִיץ בְּמַצָּב A שָׁוָה: E = \\frac{c \\cdot \\Delta L^2}{2}\nכָּאן: \\Delta L = L_1 - L_2",
      "translit": "He'arah: Ha-energiah ha-potentsialit E ha-atsurah ba-kfits be-matsav A shavah: E = \\frac{c \\cdot \\Delta L^2}{2}\nKan: \\Delta L = L_1 - L_2",
      "ru": "Примечание: Потенциальная энергия E, запасённая в пружине в состоянии A, равна: E = \\frac{c \\cdot \\Delta L^2}{2}\nгде: \\Delta L = L_1 - L_2"
    },
    {
      "segment_index": 9,
      "he": "שאלה 7.2:",
      "he_niqqud": "שְׁאֵלָה 7.2:",
      "translit": "She'elah 7.2:",
      "ru": "Вопрос 7.2:"
    },
    {
      "segment_index": 10,
      "he": "בתרשים מתואר מכשיר מעבדה המיועד לפליטת כדוריות כלפי מעלה.",
      "he_niqqud": "בַּתַּרְשִׁים מְתֹאָר מַכְשִׁיר מַעְבָּדָה הַמְּיֹעָד לִפְלִיטַת כַּדּוּרִיּוֹת כְּלַפֵּי מַעְלָה.",
      "translit": "Ba-tarsim meto'ar makhshir ma'abadah ha-meyu'ad li-flitat kaduriot klapei ma'alah.",
      "ru": "На схеме показан лабораторный прибор, предназначенный для выброса шариков вверх."
    },
    {
      "segment_index": 11,
      "he": "הכדוריות נפלטות כתוצאה משחרור קפיץ בורגי שנלחץ מלכתחילה.",
      "he_niqqud": "הַכַּדּוּרִיּוֹת נִפְלָטוֹת כְּתוֹצָאָה מִשִּׁחְרוּר קְפִיץ בָּרְגִּי שֶׁנִּלְחַץ מִלְּכַתְּחִלָּה.",
      "translit": "Ha-kaduriot niflatot ke-totsa'ah mi-shikhrur kfits borgi she-nilkhats mi-lekhatchilah.",
      "ru": "Шарики выбрасываются в результате освобождения предварительно сжатой винтовой пружины."
    },
    {
      "segment_index": 12,
      "he": "במצב חופשי הקצה העליון של הקפיץ הגיע עד הקצה העליון של המכשיר.",
      "he_niqqud": "בְּמַצָּב חָפְשִׁי הַקָּצֶה הָעֶלְיוֹן שֶׁל הַקְּפִיץ הִגִּיעַ עַד הַקָּצֶה הָעֶלְיוֹן שֶׁל הַמַּכְשִׁיר.",
      "translit": "Be-matsav khofshi ha-katseh ha-elyon shel ha-kfits higi'a ad ha-katseh ha-elyon shel ha-makhshir.",
      "ru": "В свободном состоянии верхний конец пружины достигал верхнего края устройства."
    },
    {
      "segment_index": 13,
      "he": "נתון:\nמשקל הכדורית: G = 0.5N\nמקדם הקשיחות של הקפיץ: c = 3_{N/cm}\nלחיצה תחילית של הקפיץ: h_1 = 12_{cm}\nתאוצת הכובד: g = 9.81_{m/sec^2}",
      "he_niqqud": "נָתוּן:\nמִשְׁקַל הַכַּדּוּרִית: G = 0.5N\nמְקַדֵּם הַקְּשִׁיחוּת שֶׁל הַקְּפִיץ: c = 3_{N/cm}\nלְחִיצָה תְּחִלִּית שֶׁל הַקְּפִיץ: h_1 = 12_{cm}\nתְּאוּצַת הַכֹּבֶד: g = 9.81_{m/sec^2}",
      "translit": "Natun:\nMishkal ha-kadurit: G = 0.5N\nMekadem ha-kheshikhut shel ha-kfits: c = 3_{N/cm}\nLekhitsah tekhilit shel ha-kfits: h_1 = 12_{cm}\nTe'utsat ha-koved: g = 9.81_{m/sec^2}",
      "ru": "Дано:\nВес шарика: G = 0.5N\nКоэффициент жесткости пружины: c = 3_{N/cm}\nНачальное сжатие пружины: h_1 = 12_{cm}\nУскорение свободного падения: g = 9.81_{m/sec^2}"
    },
    {
      "segment_index": 14,
      "he": "חשב: א. את המהירות, שבה נפלטת הכדורית מתוך המכשיר. ב. את הגובה H, אליו הכדורית תעלה. הזנח את החיכוך במכשיר ואת התנגדות האוויר.",
      "he_niqqud": "חַשֵּׁב: א. אֶת הַמְּהִירוּת, שֶׁבָּהּ נִפְלֶטֶת הַכַּדּוּרִית מִתּוֹךְ הַמַּכְשִׁיר. ב. אֶת הַגֹּבַהּ H, אֵלָיו הַכַּדּוּרִית תַּעֲלֶה. הַזְנַח אֶת הַחִכּוּךְ בַּמַּכְשִׁיר וְאֶת הִתְנַגְּדוּת הָאֲוִיר.",
      "translit": "Khashev: a. et ha-mehirut, she-bah nifleteret ha-kadurit mi-tokh ha-makhshir. b. et ha-govah H, elav ha-kadurit ta'aleh. Haznakh et ha-khikhukh ba-makhshir ve-et hitnagdut ha-avir.",
      "ru": "Рассчитайте: а. Скорость, с которой шарик вылетает из устройства. б. Высоту H, на которую поднимется шарик. Пренебрегите трением в устройстве и сопротивлением воздуха."
    },
    {
      "segment_index": 15,
      "he": "הערה: האנרגיה המצטברת בעבודת כוח אלסטי של קפיץ בורגי על מסלול h שווה: E = \\frac{c \\cdot h^2}{2}\nכאן: c - מקדם הקשיחות של הקפיץ\nיכל הסעיפים שווים בערכם",
      "he_niqqud": "הֶעָרָה: הָאֶנֶרְגְּיָה הַמִּצְטַבֶּרֶת בַּעֲבוֹדַת כֹּחַ אֶלַסְטִי שֶׁל קְפִיץ בָּרְגִּי עַל מַסְלוּל h שָׁוָה: E = \\frac{c \\cdot h^2}{2}\nכָּאן: c - מְקַדֵּם הַקְּשִׁיחוּת שֶׁל הַקְּפִיץ\nכָּל הַסְּעִיפִים שָׁוִים בְּעֶרְכָּם",
      "translit": "He'arah: Ha-energiah ha-mitstaberet be-avodat ko'akh elasti shel kfits borgi al maslul h shavah: E = \\frac{c \\cdot h^2}{2}\nKan: c - mekadem ha-kheshikhut shel ha-kfits\nKol ha-se'ifim shavim be-erkam",
      "ru": "Примечание: Энергия, накопленная при работе силы упругости винтовой пружины на пути h, равна: E = \\frac{c \\cdot h^2}{2}\nгде: c - коэффициент жесткости пружины.\nВсе пункты равнозначны."
    }
  ]
}
